using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.Rendering.RenderGraphModule;using UnityEngine.Experimental.Rendering;
public static class Hair208Layers{
 public static Hair208View Current;public static bool Enabled;public static int scale=2;public static readonly string[]Names={"Skin","Hair","SkinHairFront"};
 public sealed class Set:IDisposable{public RTHandle rgba,meta,uv,world,depth;public Set(string n,int s){int w=9*s,h=8*s;rgba=RTHandles.Alloc(w,h,colorFormat:GraphicsFormat.R8G8B8A8_SRGB,filterMode:FilterMode.Point,name:n+"RGBA");meta=RTHandles.Alloc(w,h,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"Meta");uv=RTHandles.Alloc(w,h,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"UV");world=RTHandles.Alloc(w,h,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"World");depth=RTHandles.Alloc(w,h,depthBufferBits:DepthBits.Depth32,name:n+"Depth");}public void Dispose(){rgba?.Release();meta?.Release();uv?.Release();world?.Release();depth?.Release();}}
 public static Set[]Sets;static int allocated;public static void Ensure(){if(Sets!=null&&allocated==scale)return;DisposeBuffers();allocated=scale;Sets=Names.Select(n=>new Set("208"+n,scale)).ToArray();}public static void DisposeBuffers(){if(Sets!=null)foreach(var s in Sets)s.Dispose();Sets=null;}
}
public sealed class Hair208Feature:ScriptableRendererFeature{
 Pass pass;public override void Create(){pass=new Pass{renderPassEvent=RenderPassEvent.AfterRenderingTransparents};}public override void AddRenderPasses(ScriptableRenderer r,ref RenderingData d){if(Hair208Layers.Enabled&&Hair208Layers.Current&&d.cameraData.camera==Hair208Layers.Current.cropCamera)r.EnqueuePass(pass);}
 sealed class Data{public int mode;public Renderer[]rr;public Material[]mm;public int[]ss;}
 sealed class Pass:ScriptableRenderPass{public override void RecordRenderGraph(RenderGraph g,ContextContainer frame){Hair208Layers.Ensure();var v=Hair208Layers.Current;for(int p=0;p<3;p++){using var b=g.AddRasterRenderPass<Data>("208 crop-only "+Hair208Layers.Names[p],out var d);var t=Hair208Layers.Sets[p];b.SetRenderAttachment(g.ImportTexture(t.rgba),0,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.meta),1,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.uv),2,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.world),3,AccessFlags.Write);b.SetRenderAttachmentDepth(g.ImportTexture(t.depth),AccessFlags.Write);b.UseAllGlobalTextures(true);var res=frame.Get<UniversalResourceData>();if(res.mainShadowsTexture.IsValid())b.UseTexture(res.mainShadowsTexture,AccessFlags.Read);b.AllowPassCulling(false);b.AllowGlobalStateModification(true);var rr=new List<Renderer>();var mm=new List<Material>();var ss=new List<int>();foreach(var r in v.source.Layers.game.sourceRenderers){var mats=r.sharedMaterials;for(int k=0;k<mats.Length;k++){int role=Mathf.RoundToInt(mats[k].GetFloat("_E151Role"));if(!(p==0?role==3:p==1?role>=11:role==3||role>=11))continue;rr.Add(r);mm.Add(mats[k]);ss.Add(k);}}d.mode=p;d.rr=rr.ToArray();d.mm=mm.ToArray();d.ss=ss.ToArray();b.SetRenderFunc(static(Data d,RasterGraphContext c)=>{c.cmd.ClearRenderTarget(RTClearFlags.All,Color.clear,1,0);c.cmd.SetGlobalFloat("_E202Part",d.mode==0?0:d.mode==1?6:9);for(int i=0;i<d.rr.Length;i++)c.cmd.DrawRenderer(d.rr[i],d.mm[i],d.ss[i],d.mm[i].FindPass("IndependentEye202"));c.cmd.SetGlobalFloat("_E202Part",-1);});}}}
}
